(function(root){'use strict';
function normalize(s){return String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/ё/g,'е').replace(/[^\p{L}\p{N}]+/gu,' ').trim();}
function index(rows,meta){return rows.map(r=>({r,n:normalize(r[1]),a:r[2].split('|').map(normalize),region:normalize(meta.regions[r[5]].join(' '))}));}
function search(index,q,limit=30){const tokens=normalize(q).split(' ').filter(Boolean);if(!tokens.length)return [];const exact=[],prefix=[],other=[];const first=tokens[0];for(const x of index){const names=[x.n,...x.a];if(!names.some(n=>n.startsWith(first)||n.split(' ').some(t=>t.startsWith(first))))continue;const hay=names.join(' ')+' '+x.region;if(!tokens.every(t=>hay.includes(t)))continue;const group=names.some(n=>n===normalize(q))?exact:names.some(n=>n.startsWith(normalize(q)))?prefix:other;if(group.length<limit)group.push(x.r);}return [...exact,...prefix,...other].slice(0,limit);}
function offsetAt(utc,zone){const p=new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(new Date(utc));const v=Object.fromEntries(p.map(x=>[x.type,x.value]));return (Date.UTC(+v.year,+v.month-1,+v.day,+v.hour,+v.minute,+v.second)-Math.floor(utc/1000)*1000)/3600000;}
function resolveLocal(local,zone){const wall=Date.parse(local+'Z');if(!Number.isFinite(wall))throw Error('Укажите дату и время.');const offsets=new Set();for(const h of [-48,-24,0,24,48])offsets.add(offsetAt(wall+h*3600000,zone));const matches=[];for(const off of offsets){const utc=wall-off*3600000;if(Math.abs(offsetAt(utc,zone)-off)<1e-7)matches.push({utc:new Date(utc).toISOString(),offset:off});}matches.sort((a,b)=>a.utc.localeCompare(b.utc));return {status:matches.length===0?'missing':matches.length>1?'ambiguous':'ok',matches};}
const api={normalize,index,search,offsetAt,resolveLocal};if(typeof module==='object')module.exports=api;else root.HorarPlaces=api;
})(typeof globalThis!=='undefined'?globalThis:this);
